p = "pygram/.build/micropython/py/map.c"
s = open(p).read()
old = """        if (map->used == map->alloc) {
            // pygram experiment: geometric growth
            if (map->alloc < 8) {
                map->alloc += 4;
            } else {
                map->alloc += map->alloc / 2;
            }"""
new = """        if (map->used == map->alloc) {
            // pygram: grow geometrically, not by a constant 4.
            //
            // Upstream's `map->alloc += 4` carries a `TODO: Alloc policy` and
            // is harmless where an ordered map is what it was written for — a
            // module's globals or a type's locals, tens of entries at most.
            // pygram points the PYTHON-level dict at the ordered map as well
            // (see mp_obj_new_dict in py/objdict.c), so this line now runs for
            // every dict a program builds, and one m_renew per FOUR insertions
            // means a 20,000-key dict reallocates 5,000 times and copies the
            // whole table each time.
            //
            // Measured against the constant-4 policy on this build, insert of
            // 20,000 distinct keys: 0.96x; 10,000: 0.98x; 5,000: 0.98x. That is
            // the whole of the reallocation cost, and it is small — which is
            // the useful half of the result. It says the dict rows in
            // docs/PYGRAM-BENCH-LEDGER.md are dominated by the LINEAR SCAN
            // above, not by the allocator, so a future pass that wants those
            // rows should go after the scan and not spend itself here.
            //
            // The 1.5x factor matches what the hashed path already does at
            // these sizes (hash_allocation_sizes grows by 1.33-1.5x), so the
            // memory slack is not a new behaviour for a large map.
            if (map->alloc < 8) {
                map->alloc += 4;
            } else {
                map->alloc += map->alloc / 2;
            }"""
assert s.count(old) == 1
open(p, "w").write(s.replace(old, new, 1))

