anchor = "diff --git a/py/modbuiltins.c b/py/modbuiltins.c"
assert patch.count(anchor) == 1
open("pygram/variant/patches/0001-pygram-port.patch", "w").write(patch.replace(anchor, hunk + anchor, 1))
print("folded", len(hunk), "bytes into 0001")

